func ModeTextVerbositySettings(level any) ModelSettings

Model interface {
	// GetResponse sends a request and returns a complete response.
	GetResponse(ctx context.Context, req ModelRequest) (*ModelResponse, error)

	// StreamResponse sends a request and returns a streaming response.
	StreamResponse(ctx context.Context, req ModelRequest) (*ModelStream, error)

	// GetRetryAdvice determines whether a failed call should be retried.
	GetRetryAdvice(err error) *ModelRetryAdvice

	// CalculateCost returns the USD cost for the given usage.
	CalculateCost(usage Usage) float64

	// Provider returns the provider name ("anthropic" or "openai").
	Provider() string
}

ModelBehaviorError struct {
	Message string
	Model   string
}

ModelIdentity struct {
	Raw       string
	Provider  string
	Canonical string
}

ModelProvider interface {
	// GetModel returns a Model for the given name.
	// The name may be a bare model identifier (e.g. "claude-sonnet-4-6")
	// or include a provider prefix (e.g. "anthropic/claude-sonnet-4-6").
	GetModel(name string) (Model, error)

	// Close releases any resources held by this provider.
	Close() error
}

ModelResponse struct {
	Items     []RunItem
	Usage     Usage
	Raw       any     // provider-specific raw response for debugging
	CostUSD   float64 // estimated cost in USD (set by runner after model returns)
	CostKnown bool    // whether cost estimate is considered reliable
	// EndTurn carries an explicit provider decision about whether this response
	// ends the current user turn. nil means the provider omitted the signal and
	// the runner falls back to its normal response classification; false requests
	// another model step even when the response contains text but no tool call.
	EndTurn *bool
	// ContextTokens is the provider-normalized prompt-side size of this
	// request (set by the runner, see usageContextTokens): the true context
	// pressure regardless of whether the provider reports cache tokens as a
	// subset of input (OpenAI-style) or additive to it (Anthropic-style).
	// Hosts must use this for window gauges instead of summing usage fields.
	ContextTokens int64
}

ModelRetryAdvice struct {
	ShouldRetry  bool
	RetryAfterMS int64
	Reason       string
}

// Merge returns a new ModelSettings with overrides from other applied.
// Non-zero/non-nil values in other take precedence.
func (s ModelSettings) Merge(other ModelSettings) ModelSettings

ModelStream struct {
	Events <-chan ModelStreamEvent
	done   chan *ModelResponse
}

ModelUsageEntry struct {
	InputTokens              int64 `json:"input_tokens"`
	OutputTokens             int64 `json:"output_tokens"`
	CacheReadInputTokens     int64 `json:"cache_read_input_tokens"`
	CacheCreationInputTokens int64 `json:"cache_creation_input_tokens"`
}

// GetModel parses the model name for a provider prefix and delegates to the
// appropriate registered provider. Names whose first "/" segment is not a
// registered provider prefix are rejected; model IDs that themselves contain
// "/" must be double-prefixed (e.g. "openrouter/anthropic/claude-...").
func (mp *MultiProvider) GetModel(name string) (Model, error)

// NormalizeModelName strips the provider prefix only when it routes to a
// registered provider, preserving model IDs that contain "/" as part of the
// ID (e.g. "openrouter/anthropic/claude-..." → "anthropic/claude-...").
// Names with an unregistered prefix are returned unchanged, but note GetModel
// rejects them: slashed model IDs are only routable when double-prefixed with
// a registered provider.
func (mp *MultiProvider) NormalizeModelName(name string) string

MultiProvider struct {
	mu            sync.RWMutex
	providers     map[string]ModelProvider
	defaultPrefix string
}

// MutatingToolEnabled reports whether a mutating tool may be considered
// enabled for the run's access context. The runner's exact-name filter remains
// the authorization boundary; this helper lets access-aware IsEnabled methods
// recognize the same host-trusted exception instead of rejecting it early.
func MutatingToolEnabled(ctx *RunContext, toolName string) bool

// NewChildEventStream creates a child stream for a subagent.
// Shares the writer and write mutex, auto-tags events with taskID.
func NewChildEventStream(parent *EventStream, taskID string) *EventStream

// NewChildTracker creates a child tracker for a subagent.
// It keeps its own event/activity state, but forwards LLM usage (cost and
// tokens, including cache tokens) and tool-call counts up the parent chain as
// they happen, so the run-level tracker always reflects total consumption —
// even for subagents that later fail or are cancelled, and for nested
// subagents.
func NewChildTracker(parent *ProgressTracker, taskID string) *ProgressTracker

// NewMultiProvider creates a MultiProvider with the given default prefix.
// The default prefix is used when a model name contains no "/" separator.
func NewMultiProvider(defaultPrefix string) *MultiProvider

// NewRunnerWithProvider creates a Runner backed by the given ModelProvider.
// The provider resolves model names to Model implementations on each call.
func NewRunnerWithProvider(provider ModelProvider) *Runner

// NormalizeSubAgentDependencyPolicy maps empty/unknown policy values to the
// conservative default.
func NormalizeSubAgentDependencyPolicy(policy SubAgentDependencyPolicy) SubAgentDependencyPolicy

// NormalizeToolAccessLevel maps caller/user-facing access strings to the
// runner's two enforcement tiers. Empty means the historical default (full).
// Unknown non-empty values fail closed to read-only so a typo cannot silently
// grant write tools.
func NormalizeToolAccessLevel(level ToolAccessLevel) ToolAccessLevel

OutputGuardrail struct {
	Name string
	Fn   func(ctx *RunContext, agent *Agent, output any) (*GuardrailResult, error)
}

OutputGuardrailResult struct {
	GuardrailName     string
	Output            any
	TripwireTriggered bool
}

OutputGuardrailTripwireTriggered struct {
	GuardrailName string
	Result        GuardrailResult
}

// Validate checks that raw JSON conforms to the schema by attempting to parse it.
// Returns the parsed value on success, or an error describing the validation failure.
func (s *OutputSchema) Validate(raw string) (any, error)

OutputSchema struct {
	Name    string          `json:"name"`
	Schema  json.RawMessage `json:"schema"`
	Strict  bool            `json:"strict"`
	ParseFn func(raw string) (any, error)
}

// ParseModelPrefix splits a "prefix/model" string into its components.
// If there is no "/" the prefix is empty and model is the full string.
func ParseModelPrefix(name string) (prefix, model string)

// PlanRunItemsCompactionForRequest is the plan-returning variant of
// MaybeCompactRunItemsForRequest. The returned plan's After includes the
// request overhead so it is directly comparable with the returned before.
func PlanRunItemsCompactionForRequest(items []RunItem, cfg CompactionConfig, requestOverheadTokens int) (CompactionPlan, int, bool, string)

PlatformHooks struct {
	Tracker     *ProgressTracker
	EventStream *EventStream
	Turn        int // current conversation turn, set by caller
	// Activity optionally tracks file operations for parent visibility.
	// Set on child hooks to let the parent query sub-agent activity.
	Activity *SubAgentActivity
	// toolStart tracks when each tool began for duration calculation.
	// Protected by mu since tools execute in parallel goroutines.
	mu        sync.Mutex
	toolStart map[string]time.Time
	// llmAttemptID is the id of the most recent model call attempt (the
	// generation span UUID also carried by llm_attempt events). OnLLMEnd
	// stamps it onto final assistant_thinking events so consumers can match
	// them to the assistant_thinking_delta chunk stream of the same call.
	// Guarded by mu; each hooks instance observes sequential model calls
	// (sub-agent runs get their own PlatformHooks).
	llmAttemptID string
}

ProgressEvent struct {
	Timestamp time.Time `json:"timestamp"`
	EventType string    `json:"eventType"`
	Summary   string    `json:"summary"`
}

// RecordLLMUsage accumulates cost and token counts from a single LLM call
// so the tracker's Snapshot() stays current between session-complete events.
// Child trackers forward every call up the parent chain, so run-level totals
// (cost caps, session metrics) include subagent usage — cache tokens included
// — as it happens, and usage from subagents that later fail or are cancelled
// is never lost. Nested subagents roll up the same way, one level at a time.
func (t *ProgressTracker) RecordLLMUsage(model string, costUSD float64, usage Usage)

apis.doc:
RecordSessionComplete logs session completion with final metrics.
Note: cost/token accumulation is handled per-call by RecordLLMUsage;
this method only emits the session_complete event and OTel span.

apis.signature:
// RecordSessionComplete logs session completion with final metrics.
// Note: cost/token accumulation is handled per-call by RecordLLMUsage;
// this method only emits the session_complete event and OTel span.
func (t *ProgressTracker) RecordSessionComplete(model string, costUSD float64, numTurns int, usage Usage, duration time.Duration, stopReason string)

// SetRootSpanID sets the parent span ID for all record.go-emitted spans.
// Call this when the agentrun-level trace is created and update when phases change.
func (t *ProgressTracker) SetRootSpanID(id string)

// WriteResult records a terminal result summary for compatibility with hosts
// that use the progress tracker as their status source.
func (t *ProgressTracker) WriteResult(status, prURL, errMsg, failedStep string)

ProgressTracker struct {
	mu                       sync.Mutex
	currentStep              string
	sessionNumber            int32
	lastActivity             string
	agentCount               int32
	toolCallCount            int32
	costUsd                  float64
	inputTokens              int64
	outputTokens             int64
	cacheReadInputTokens     int64
	cacheCreationInputTokens int64
	modelUsage               map[string]ModelUsageEntry
	apiRetries               int32
	events                   []ProgressEvent

	// Subagent tracking: maps task_id to agent metadata.
	taskAgents map[string]AgentMeta

	// lastAssistantText stores the full text from the most recent assistant message.
	lastAssistantText string

	// lastAssistantThinking stores thinking content separately.
	lastAssistantThinking string

	// Per-session counters (reset on SetSession).
	sessionToolCallCount int32
	sessionCostUsd       float64

	// pendingEvents collects session-level events for K8s Event emission.
	pendingEvents []ProgressEvent

	// maxToolResultBytes optionally limits tool result and input_raw content in the event stream.
	// Values <= 0 disable truncation.
	maxToolResultBytes int

	// taskID is set on child trackers — auto-tags all log entries with this task ID.
	taskID string

	// parent points to the parent tracker (for child trackers only).
	parent *ProgressTracker

	// tp emits structural OTel spans for metrics/observability events.
	tp TracingProcessor
	// rootSpanID is the parent span ID for record.go-emitted spans (phase,
	// session, subagent, retry, compaction). Updated by plan.go when the
	// active phase changes.
	rootSpanID string
	// subagentSpans holds the open lifecycle span per subagent task so
	// RecordSubagentCompleted can end the span RecordSubagentStarted opened
	// (one span covering the subagent's real lifetime).
	subagentSpans map[string]*Span
}

// RemoveAllToolsHandoffInputFilter is a prebuilt handoff InputFilter that strips
// every tool call and tool output item from the history handed to the receiving
// agent. This keeps the target agent focused on the conversation without
// inheriting potentially large or irrelevant tool-call noise from the prior
// agent. Reasoning and approval items are dropped too: some providers reject
// reasoning blocks whose sibling tool call was removed. Pass it via
// WithInputFilter.
func RemoveAllToolsHandoffInputFilter(input []RunItem, _ []RunItem) []RunItem

// ResolveModeRouting resolves the effective model and reasoning for the top-level
// agent from the mode's default routing.
func ResolveModeRouting(baseModel, provider string, routing *ModeModelRouting) ModeRoutingResolution

// ResolveModelForProvider maps short aliases (small/medium/large) and the
// empty model name to concrete defaults for the selected provider. Other
// names pass through trimmed; providers reject incompatible model IDs.
//
// Prefer using MultiProvider.GetModel() which handles this internally.
// This function is kept for call sites that need resolution without constructing a Model.
func ResolveModelForProvider(model, provider string) string

// ResolveRoleModeRouting resolves the effective model and reasoning for a
// specialist role. Priority:
// 1. mode role override
// 2. mode defaults
func ResolveRoleModeRouting(
	baseModel, provider, roleName string,
	routing *ModeModelRouting,
) ModeRoutingResolution

// RestoreRunItems converts persisted, provider-neutral checkpoint history back
// into replayable items. resolveAgent is optional; when supplied it restores
// item provenance by stable agent name.
func RestoreRunItems(items []LLMRunItemSnapshot, resolveAgent func(string) *Agent) ([]RunItem, error)

RetryBackoffSettings struct {
	InitialDelayMS int
	MaxDelayMS     int
	Multiplier     float64
}

// DelayForAttempt calculates the backoff delay for a given retry attempt (0-indexed).
// Partially-populated policies are normalized: an unset Multiplier or
// MaxDelayMS would otherwise collapse every later delay to 0 ms and hot-loop
// retries against a failing provider. An explicit InitialDelayMS <= 0 keeps
// meaning "retry immediately".
func (p *RetryPolicy) DelayForAttempt(attempt int) time.Duration

RetryPolicy struct {
	MaxRetries int
	Backoff    RetryBackoffSettings
}

