func (r *RunResult) AllInterruptions() []*Interruption

RunResult struct {
	FinalOutput                any // string or structured (parsed from OutputSchema)
	LastAgent                  *Agent
	NewItems                   []RunItem
	RawResponses               []ModelResponse
	InputGuardrailResults      []InputGuardrailResult
	OutputGuardrailResults     []OutputGuardrailResult
	ToolInputGuardrailResults  []ToolGuardrailResult
	ToolOutputGuardrailResults []ToolGuardrailResult
	ActionAuditRecords         []ActionAuditRecord
	Usage                      Usage
	Interruption               *Interruption   // non-nil if run was interrupted (e.g. approval gate); first of Interruptions
	Interruptions              []*Interruption // all pending interruptions from the turn (parallel tool calls can trigger several)
	LastResponseID             string          // last model response ID for continuation

	// FinalHistory is the complete post-run conversation state: the input
	// items as the runner last used them (after any mid-run compaction
	// rewrote or summarized older items) plus every item generated during
	// the run. Hosts that replay full transcripts across turns should feed
	// this back as the next Run's input (after appending the new user
	// message) instead of re-deriving history from NewItems — replaying
	// input+NewItems after a compaction would resend the uncompacted
	// history. On interrupted runs it may end with an unresolved tool
	// approval; resolve (or drop) pending calls before replaying.
	FinalHistory []RunItem
}

// CalculateCost returns the USD cost estimate for the given usage.
// Safe to call regardless of how the runner was constructed.
func (r *Runner) CalculateCost(usage Usage) float64

// ExecuteApprovedTool resumes a previously interrupted approval request using
// the same runner preparation path as ordinary tool execution. The tool has
// already been approved by the host, so this method executes the matching tool
// directly while still applying access adapters, IsEnabled filtering, policy
// timeouts, hooks, tracing, and tool input/output guardrails.
//
// Tracing: pass the originating run's cfg.Trace (and ParentSpanID) so the
// approved tool's span joins that run's waterfall; when cfg.Trace is nil a
// fresh single-call trace is created for this execution.
func (r *Runner) ExecuteApprovedTool(ctx context.Context, agent *Agent, call ToolCallData, cfg RunConfig) (RunItem, []ToolGuardrailResult, []ToolGuardrailResult, bool, error)

// Run executes an agent with the given input and returns the result.
// It runs the agent loop: LLM call → process response → tools/handoff/final → repeat.
//
// Partial results: when the run ends early with the conversation still
// intact — the turn budget runs out (MaxTurnsExceeded), the context is
// cancelled mid-run (host pause/shutdown, run deadline), or the turn fails
// after at least one completed turn (model/API error past retries and
// fallbacks, guardrail trip) — Run returns the accumulated run state
// alongside the non-nil error (io.Reader-style partial-result semantics).
// FinalHistory on that partial result is the replay-safe post-fold
// transcript of every completed turn, so hosts can persist it and continue
// the session in a follow-up run instead of losing the accumulated context.
func (r *Runner) Run(ctx context.Context, agent *Agent, input []RunItem, cfg RunConfig) (*RunResult, error)

Runner struct {
	model    Model
	provider ModelProvider // optional; when set, resolves model per-call
	// DefaultHooks are applied to sub-agent runs that don't specify their own hooks.
	// This ensures nested agent tool calls (e.g. agent_explore → Grep) appear in the
	// activity log alongside the parent's events.
	DefaultHooks RunHooks
}

// Err returns the terminal error from a streamed run, if any. Call it after
// FinalResult or after Events has closed. FinalResult keeps the original
// non-breaking API shape, so this method is the error side channel for
// streamed runs.
func (s *StreamedRunResult) Err() error

// FinalResult blocks until the run completes and returns the result.
// It is safe to call multiple times; every call returns the same result.
func (s *StreamedRunResult) FinalResult() *RunResult

StreamedRunResult struct {
	Events <-chan StreamEvent
	done   chan *RunResult

	// resultOnce/result make FinalResult idempotent: only the first call
	// receives from done, later calls return the cached result instead of
	// nil from the closed channel.
	resultOnce sync.Once
	result     *RunResult

	mu  sync.Mutex
	err error
}

