	path, err := workspacePath(workDir, params.Path)
	if err != nil {
		return agentsdk.ToolResult{}, err
	}
	data, truncated, err := readFileNoFollowBounded(workDir, path, params.StartLine, params.EndLine)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
