Description.expression:
func (t *BashPollTool) Description() string {
	return "Polls a background bash job started by BashStart. By default returns only output produced since the previous poll (incremental), plus status. Optionally waits before returning so long jobs do not require tight polling."
}

Execute.expression:
func (t *BashPollTool) Execute(ctx context.Context, input json.RawMessage, workDir string) (agentsdk.ToolResult, error) {
	var in asyncIDInput
	if err := json.Unmarshal(input, &in); err != nil {
		return agentsdk.ToolResult{Content: fmt.Sprintf("Invalid input: %v", err), IsError: true}, nil
	}
	job, ok := t.Manager.get(strings.TrimSpace(in.ID))
	if !ok {
		return agentsdk.ToolResult{Content: "unknown job id: " + in.ID, IsError: true}, nil
	}
	if wait := clampPollWait(in.WaitMS); wait > 0 {
		select {
		case <-job.done:
		case <-ctx.Done():
		case <-time.After(wait):
		}
	}
	snap := job.snapshot()
	if in.Incremental == nil || *in.Incremental {
		out, gap := job.consumeNewOutput()
		if out == "" {
			out = "(no new output since last poll)"
		}
		snap.Output = out
		if gap {
			snap.Note = "some output between polls exceeded the retention cap and was discarded"
		}
	}
	data, err := json.MarshalIndent(snap, "", "  ")
	if err != nil {
		return agentsdk.ToolResult{Content: fmt.Sprintf("Error: %v", err), IsError: true}, nil
	}
	return agentsdk.ToolResult{Content: string(data)}, nil
}

