commandBlocked.expression:
// commandBlocked applies the tool-layer command policy for the given mode.
// The destructive-command classifier is defense in depth for hosts without an
// enforcing OS sandbox: when the executor reports filesystem enforcement, the
// classifier is skipped and only git policy (remote-side effects the sandbox
// cannot contain) applies.
func (t *BashTool) commandBlocked(mode policy.PermissionMode, command string) (bool, string) {
	executor := t.Executor
	if executor == nil {
		executor = sandbox.Default()
	}
	fsEnforced := sandbox.ExecutorEnforcesFilesystem(executor, mode)
	if policy.NormalizeGitRemoteWrites(t.GitRemoteWrites) == policy.GitRemoteWritesDisabled && !fsEnforced {
		return true, "Command blocked: GitRemoteWrites=disabled requires an enforcing command sandbox " +
			"so Git credentials remain unavailable to subprocesses"
	}
	return isCommandBlockedForGitRemoteWrites(mode, t.GitRemoteWrites, command, fsEnforced)
}

execute.expression:
func (t *BashTool) execute(ctx context.Context, input json.RawMessage, workDir string, mode policy.PermissionMode) (agentsdk.ToolResult, error) {
	var in bashInput
	if err := json.Unmarshal(input, &in); err != nil {
		return agentsdk.ToolResult{Content: fmt.Sprintf("Invalid input: %v", err), IsError: true}, nil
	}
	if in.Command == "" {
		return agentsdk.ToolResult{Content: "command is required", IsError: true}, nil
	}

	timeout := effectiveDefaultBashTimeout()
	maxTimeout := effectiveMaxBashTimeout()
	if in.Timeout > 0 {
		timeout = time.Duration(in.Timeout) * time.Millisecond
		if timeout > maxTimeout {
			timeout = maxTimeout
		}
	}

	executor := t.Executor
	if executor == nil {
		executor = sandbox.Default()
	}

	mode = policy.NormalizePermissionMode(string(mode))
	req := sandbox.Request{
		Argv:           []string{"bash", "--noprofile", "--norc", "-c", in.Command},
		WorkDir:        workDir,
		PermissionMode: mode,
		Timeout:        timeout,

		AllowNetwork: mode == policy.PermissionModeWorkspaceWrite,
	}

	maxOutputBytes := effectiveMaxBashOutputBytes()
	result, err := runBoundedRequest(ctx, executor, req, maxOutputBytes)
	outputStr := result.Output
	if result.Capped {
		outputStr += bashTruncationNotice(result.TotalBytes, maxOutputBytes)
	}

	if result.TimedOut {
		return agentsdk.ToolResult{Content: outputStr + "\n[command timed out]"}, nil
	}
	if err != nil {
		return agentsdk.ToolResult{Content: fmt.Sprintf("%s\nError: %v", outputStr, err), IsError: true}, nil
	}
	if result.ExitCode != 0 {
		return agentsdk.ToolResult{Content: fmt.Sprintf("%s\nExit code: %d", outputStr, result.ExitCode)}, nil
	}
	if outputStr == "" {
		outputStr = "(no output)"
	}
	return agentsdk.ToolResult{Content: outputStr}, nil
}

